#include <bits/stdc++.h>#define endl '\n'#define inf 0x3f3f3f3fusing namespace std;using ll = long long;constexpr int maxn = 2e6 + 10;int a[maxn], cnt[maxn], dist[maxn];int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);    cout.tie(nullptr);    freopen("migrate.in", "r", stdin);    freopen("migrate.out", "w", stdout);    int c, t;    cin >> c >> t;    while (t --) {        memset(cnt, 0, sizeof cnt);        memset(dist, inf, sizeof dist);        int n, m;        cin >> n >> m;        for(int i = 1; i <= n; i++) cin >> a[i];        // BFS        queue<int> q;        q.push(1);        while (!q.empty()) {            int dot = q.front();            q.pop();            for(int i = dot + 1; i <= n; i++) {                if (i == dot) continue;                int sum = abs(a[dot] - a[i]);                if (sum > m) continue;                if (dist[i] < sum) continue;                else if (dist[i] == sum) cnt[i] ++;                else {                    dist[i] = sum;                    cnt[i] = 0;                }                q.push(i);            }        }int ans = 0;        for(int i = 1; i <= n; i++) ans += cnt[i];        cout << ans << endl;    }return 0;}